"""Builds reports/COSTS.md from ledger.json (via costs.py logic) and the experiment Cost figures."""
import json, statistics, subprocess, sys
from paths import ROOT
sys.path.insert(0, f"{ROOT}/scripts")
subprocess.run([sys.executable, f"{ROOT}/scripts/costs.py"], capture_output=True)
R = json.load(open(f"{ROOT}/results/costs.json")); E1c = json.load(open(f"{ROOT}/results/costs_exp1c.json"))
L = json.load(open(f"{ROOT}/ledger.json"))
from costs import astra, fable, toks
# split the shared tag repeat_seq_08 into the killed first try (before 09:02 Nov 17) and the rerun
def agg(pred):
    a = dict(cost=0, pt=0, ca=0, ct=0, rs=0, astra=0, astra_nc=0, fable=0, fable_nc=0, calls=0)
    for c in L["calls"]:
        if not pred(c): continue
        pt, ca, ct, rs = toks(c["usage"]); A = astra(pt, ca, ct); F = fable(pt, ca, ct)
        a["cost"] += c["cost"]; a["pt"] += pt; a["ca"] += ca; a["ct"] += ct; a["rs"] += rs; a["calls"] += 1
        a["astra"] += A["cached"]; a["astra_nc"] += A["uncached"]; a["fable"] += F["cached"]; a["fable_nc"] += F["uncached"]
    return a
tag = lambda c: c["tag"].split("/")[0]
killed08 = lambda c: tag(c) == "repeat_seq_08" and c["ts"] < "2026-11-17 09:02"
rerun08 = lambda c: tag(c) == "repeat_seq_08" and c["ts"] >= "2026-11-17 09:02"
ATT_EARLY = ["repair_flash_1", "repair_flash_2", "repair_flash_3", "repair_flash_4", "repair_flash_5"]
ATT_REP = ["repeat_flash_01"] + [f"repeat_seq_{i:02d}" for i in range(2, 11)]
SUCC = {"repair_flash_1", "repeat_seq_03", "repeat_seq_05", "repeat_seq_07", "repeat_seq_09"}
def att(t): return agg(rerun08 if t == "repeat_seq_08" else (lambda c, t=t: tag(c) == t))
rows = {t: att(t) for t in ATT_EARLY + ATT_REP}
rep_spend = agg(lambda c: tag(c).startswith("repeat_"))  # includes orphans and the killed 08 try
orph = agg(lambda c: tag(c) in ("repeat_flash_02", "repeat_flash_03", "repeat_flash_09", "repeat_flash_10") or killed08(c))
leak = agg(lambda c: tag(c).startswith("leak_perm"))
strict = {t: agg(lambda c, t=t: tag(c) == t) for t in ["raw1shot_flash_32k", "raw1shot_kimik3_32k", "raw1shot_qwenmax_32k"]}
total = agg(lambda c: True)
def f(x): return f"${x:.3f}"
def med(v): return statistics.median(v)
rc = [rows[t]["cost"] for t in ATT_REP]; ac = [rows[t]["cost"] for t in ATT_EARLY + ATT_REP]
ra = [rows[t]["astra"] for t in ATT_REP]; rf = [rows[t]["fable"] for t in ATT_REP]
nsucc_rep = sum(t in SUCC for t in ATT_REP); nsucc_all = sum(t in SUCC for t in ATT_EARLY + ATT_REP)
o = []
o.append("# Exp 4b costs (generated by scripts/make_costs_md.py)\n")
o.append(f"Ledger total (Exp 4b, Together, actual): **{f(total['cost'])}** over {total['calls']} calls. Prices for repricing checked Nov 17, 2026 (PT):")
o.append("- gpt-6-astra (OpenAI): $10 input, $1 cached input, $50 output per 1M tokens; prompts over 272K input tokens cost 2x input/cache and 1.5x output for the whole request. https://developers.openai.com/api/docs/models/gpt-6-astra and https://developers.openai.com/api/docs/pricing")
o.append("- \"Fable\" = Claude Fable 5.2 (Anthropic, released Nov 9, 2026, its current top model): $8 input, $0.20 cache hit, $40 output per 1M tokens, no long-context surcharge. https://platform.claude.com/docs/en/about-claude/pricing")
o.append("\nRepricing is **same tokens, their price**: our open model's token counts multiplied by the closed model's list price. A different model would read and write a different number of tokens (and Anthropic's newer tokenizer counts about 30% more tokens for the same text), so this is not an estimate of what Astra or Fable would really cost. Output includes reasoning tokens. \"Cached\" uses each provider's cache-hit price for tokens Together reported as cached and ignores cache-write premiums (a lower bound); \"no cache\" prices every input token at the full rate.\n")
o.append("## 1. One assisted attempt (Flash, tools + feedback, 8,600-weight cap)\n")
o.append("| Group | Attempts | Successes | Median per attempt | Range | Astra, same tokens (cached / no cache), median | Fable, same tokens (cached / no cache), median |")
o.append("|---|---:|---:|---:|---:|---:|---:|")
o.append(f"| Repeat batch (01-10) | {len(ATT_REP)} | {nsucc_rep} | {f(med(rc))} | {f(min(rc))}-{f(max(rc))} | {f(med(ra))} / {f(med([rows[t]['astra_nc'] for t in ATT_REP]))} | {f(med(rf))} / {f(med([rows[t]['fable_nc'] for t in ATT_REP]))} |")
o.append(f"| All Flash repair attempts (5 early + 10 repeats) | {len(ac)} | {nsucc_all} | {f(med(ac))} | {f(min(ac))}-{f(max(ac))} | {f(med([rows[t]['astra'] for t in ATT_EARLY+ATT_REP]))} / {f(med([rows[t]['astra_nc'] for t in ATT_EARLY+ATT_REP]))} | {f(med([rows[t]['fable'] for t in ATT_EARLY+ATT_REP]))} / {f(med([rows[t]['fable_nc'] for t in ATT_EARLY+ATT_REP]))} |")
o.append("\nPer attempt (actual Together cost; tokens = input / cached / output incl. reasoning):\n")
o.append("| Attempt | Result | Input | Cached | Output (reasoning) | Together | Astra cached / no cache | Fable cached / no cache |")
o.append("|---|---|---:|---:|---:|---:|---:|---:|")
for t in ATT_EARLY + ATT_REP:
    r = rows[t]; s = json.load(open(f"{ROOT}/runs/{t}/summary.json")); bt = (s.get("best_test") or {}).get("successes")
    res = "1024/1024" if t in SUCC else (f"{bt}/1024" if bt is not None else "no submission")
    o.append(f"| {t} | {res} | {r['pt']:,} | {r['ca']:,} | {r['ct']:,} ({r['rs']:,}) | {f(r['cost'])} | {f(r['astra'])} / {f(r['astra_nc'])} | {f(r['fable'])} / {f(r['fable_nc'])} |")
o.append(f"\n## 2. Full repeat batch\n")
o.append(f"All ledger calls tagged repeat_*: **{f(rep_spend['cost'])}** ({rep_spend['calls']} calls), including {f(orph['cost'])} on runs that were killed and do not count as attempts (orphans repeat_flash_02/03/09/10 and the first repeat_seq_08 try cut off by the box restart). Same tokens at Astra prices: {f(rep_spend['astra'])} cached / {f(rep_spend['astra_nc'])} no cache; at Fable prices: {f(rep_spend['fable'])} / {f(rep_spend['fable_nc'])}.")
o.append(f"\nCost per successful edit, repeat batch = total repeat spend / successes = {f(rep_spend['cost'])} / {nsucc_rep} = **{f(rep_spend['cost']/nsucc_rep)}** (Astra same tokens {f(rep_spend['astra']/nsucc_rep)}-{f(rep_spend['astra_nc']/nsucc_rep)}; Fable {f(rep_spend['fable']/nsucc_rep)}-{f(rep_spend['fable_nc']/nsucc_rep)}).")
o.append(f"\nLeakage-check runs (permuted network, 3 attempts): {f(leak['cost'])}; Astra same tokens {f(leak['astra'])} / {f(leak['astra_nc'])}; Fable {f(leak['fable'])} / {f(leak['fable_nc'])}.")
o.append("\nStrict 1:1 one-shots in Exp 4b (one call each, ~352k-488k input tokens, so Astra's >272K long-context rate applies):\n")
o.append("| Run | Input | Output | Together | Astra cached / no cache | Fable cached / no cache |"); o.append("|---|---:|---:|---:|---:|---:|")
for t, r in strict.items(): o.append(f"| {t} | {r['pt']:,} | {r['ct']:,} | {f(r['cost'])} | {f(r['astra'])} / {f(r['astra_nc'])} | {f(r['fable'])} / {f(r['fable_nc'])} |")
# Exp 4 strict one-shots: token counts from the Exp 4 Notion row (logs are on the old box), no cache info
e4 = {"DeepSeek-V4.1-Flash-1017": (351761, 31348), "Qwen3.7-Plus": (488125, 10516), "DeepSeek-V4-Pro-0813": (351735, 5523), "Muse-Spark-Open-816B-A42B": (351850, 13094)}
e4a = sum(astra(p, 0, c)["uncached"] for p, c in e4.values()); e4f = sum(fable(p, 0, c)["uncached"] for p, c in e4.values())
o.append("\n## 3. Cost per experiment\n")
o.append("| Experiment | Actual cost | Source | Same tokens at Astra prices | Same tokens at Fable prices |"); o.append("|---|---:|---|---:|---:|")
o.append("| Exp 1 (which game, raw weights) | $0.288 | Notion Cost | not repriced (no token log on this box) | not repriced |")
o.append("| Exp 1b (heatmaps vs raw) | $1.644 | Notion Cost | not repriced (no token log on this box) | not repriced |")
o.append(f"| Exp 1c (reasoning budget, smaller views) | $2.681 | exp1c/results/paid/ledger.jsonl ({E1c['calls']} calls) | ${E1c['astra']:.2f} (no cache) | ${E1c['fable']:.2f} (no cache) |")
o.append("| Exp 2 (MinAtar repairs from heatmaps) | $0.520 | Notion Cost | not repriced (no token log on this box) | not repriced |")
o.append(f"| Exp 4 (strict 1:1 car + first tool run) | $1.350 | Notion Cost | 4 strict one-shots only: ${e4a:.2f} (no cache) | ${e4f:.2f} (no cache) |")
o.append(f"| Exp 4b (this ledger) | {f(total['cost'])} | exp4b/ledger.json | {f(total['astra'])} cached / {f(total['astra_nc'])} no cache | {f(total['fable'])} / {f(total['fable_nc'])} |")
tot = 0.2882 + 1.6437 + 2.6805 + 0.52 + 1.35 + total["cost"]
o.append(f"\n## 4. Total project cost\n\n**${tot:.2f}** (Exp 1 $0.29 + 1b $1.64 + 1c $2.68 + 2 $0.52 + 4 $1.35 + 4b {f(total['cost'])}). Exp 1, 1b, 2 and 4 use the Notion Cost figures because their ledgers are not on this box. The Exp 4b part stays under the $10 budget set on Nov 16.")
n_est = sum(bool(c.get("estimated")) for c in L["calls"]); est_cost = sum(c["cost"] for c in L["calls"] if c.get("estimated"))
o.append("\n## Limits\n- Repricing assumes the closed model would use the same tokens. It would not: it might need fewer turns or more reasoning. Treat it as a price comparison per token, not a forecast.\n- Cache treatment differs by provider; the cached column is a lower bound because cache writes are not charged.\n- " + str(n_est) + f" Exp 4b calls (${est_cost:.3f}; timed-out or cut-off streams with no usage report) are charged at a conservative estimate in our ledger.\n- Batch/flex discounts (50% at both providers) are not applied.")
open(f"{ROOT}/reports/COSTS.md", "w").write("\n".join(o) + "\n")
print("\n".join(o))
